function describe(id) {
  return DESCRIPTIONS[String(id || "")] || ""
}

// Modifiers as the glyphs a Mac keyboard prints; other keys by a short name.
var SYMBOLS = {
  "SUPER": "⌘", "SHIFT": "⇧", "CTRL": "⌃", "ALT": "⌥",
  "RETURN": "↵", "BACKSPACE": "⌫", "ESCAPE": "Esc", "DELETE": "Del",
  "SPACE": "Space", "PRINT": "PrtSc", "PERIOD": ".", "COMMA": ",", "TAB": "⇥"
}

// "SUPER SHIFT + F" -> ["⌘", "⇧", "F"]
function keycaps(shortcut) {
  var parts = String(shortcut || "").replace(/\+/g, " ").split(/\s+/)
  var caps = []
  for (var i = 0; i < parts.length; i++) {
    var part = parts[i]
    if (!part) continue
    var upper = part.toUpperCase()
    caps.push(SYMBOLS[upper] || (part.length === 1 ? upper : part))
  }
  return caps
}
